    ffi.Pointer<objc.ObjCSelector> action, {
    objc.ObjCObject? sender,
  });
  objc.NSString? get title;
  UITraitCollection get traitCollection;
  void traitCollectionDidChange(UITraitCollection? previousTraitCollection);
  UITraitOverrides get traitOverrides;
  void unwindForSegue(
    UIStoryboardSegue unwindSegue, {
    required UIViewController towardsViewController,
  });
  void updateContentUnavailableConfigurationUsingState(
    UIContentUnavailableConfigurationState state,
  );
  void updateFocusIfNeeded();
  void updateProperties();
  void updatePropertiesIfNeeded();
  void updateTraitsIfNeeded();
